function find(p,x){ while(p[x]!==x){ p[x]=p[p[x]]; x=p[x]; } return x; }
function mst(nodes, edges){
  var sorted=edges.slice().sort(function(a,b){return a[2]-b[2];});
  var p={}; nodes.forEach(function(n){p[n]=n;});
  var res=[]; var total=0;
  sorted.forEach(function(e){ var ru=find(p,e[0]), rv=find(p,e[1]);
    if(ru!==rv){ p[ru]=rv; res.push([e[0],e[1],e[2]]); total+=e[2]; } });
  return {edges:res, total:total};
}
var EXPORTS={mst:mst};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MstForgePure = EXPORTS; }
